INSERT INTO quizzes (id, topic_id, title, title_hi, description, description_hi, difficulty, total_questions, time_limit_mins, is_previous_year, created_at) VALUES
(1304, 1199, 'Forest Policy & Conservation – Conservation Efforts Master Quiz', 'वन नीति एवं संरक्षण – संरक्षण प्रयास मास्टर क्विज़', 'Exhaustive CGPSC Prelims-level quiz testing knowledge of Chhattisgarh''s forest and wildlife conservation efforts, including Biosphere/Tiger reserves, CAMPA, Joint Forest Management, and specialized animal protection projects.', 'यह विस्तृत सीजीपीएससी प्रीलिम्स-स्तरीय क्विज़ छत्तीसगढ़ के वन और वन्यजीव संरक्षण प्रयासों के ज्ञान का परीक्षण करता है, जिसमें बायोस्फीयर/टाइगर रिजर्व, कैम्पा (CAMPA), संयुक्त वन प्रबंधन और विशेष पशु संरक्षण परियोजनाएं शामिल हैं।', 'Hard', 10, 15, 0, CURRENT_TIMESTAMP);
INSERT INTO questions (quiz_id, topic_id, question, question_hi, option_a, option_a_hi, option_b, option_b_hi, option_c, option_c_hi, option_d, option_d_hi, correct_option, explanation, explanation_hi, sort_order) VALUES
(1304, 1199, 'Match the following specific wildlife conservation projects of Chhattisgarh with their target animals:\n\nList-I (Project)\n(a) Asha Deep Pariyojana\n(b) Jamvant Pariyojana\n(c) Gajraj Pariyojana\n\nList-II (Target Animal)\n(i) Bear (Bhalu)\n(ii) Elephant (Hathi)\n(iii) Wild Buffalo (Van Bhainsa)\n\nCodes:', 'छत्तीसगढ़ की निम्नलिखित विशिष्ट वन्यजीव संरक्षण परियोजनाओं को उनके लक्षित जानवरों के साथ सुमेलित करें:\n\nसूची-I (परियोजना)\n(a) आशा दीप परियोजना\n(b) जामवंत परियोजना\n(c) गजराज परियोजना\n\nसूची-II (लक्षित जानवर)\n(i) भालू\n(ii) हाथी\n(iii) जंगली भैंसा (वन भैंसा)\n\nकूट:', '(a)-(i), (b)-(iii), (c)-(ii)', '(a)-(i), (b)-(iii), (c)-(ii)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(iii), (b)-(ii), (c)-(i)', 2, 'All three projects were initiated in 2014. ''Asha Deep'' is for the conservation of the endangered Wild Buffalo. ''Jamvant'' is for Bears (implemented in 6 forest divisions), and ''Gajraj'' is for Elephants (in 14 forest divisions).', 'तीनों परियोजनाएं 2014 में शुरू की गई थीं। ''आशा दीप'' लुप्तप्राय वन भैंसे के संरक्षण के लिए है। ''जामवंत'' भालू के लिए है (6 वन मंडलों में लागू), और ''गजराज'' हाथियों के लिए है (14 वन मंडलों में)।', 1),
(1304, 1199, 'Consider the following statements regarding Crocodile Conservation Centers in Chhattisgarh:\n\n1. Kotmi Sonar (Janjgir-Champa) is an artificial crocodile conservation reserve established in 2006-07.\n2. Bhaisadarha is a natural crocodile habitat located on the Kanger River in Bastar.\n3. The Jatloor River in Narayanpur district also serves as a natural crocodile conservation site.\n\nWhich of the statement(s) given above is/are correct?', 'छत्तीसगढ़ में मगरमच्छ संरक्षण केंद्रों के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. कोटमी सोनार (जांजगीर-चांपा) 2006-07 में स्थापित एक कृत्रिम मगरमच्छ संरक्षण रिजर्व है।\n2. भैंसादरहा बस्तर में कांगेर नदी पर स्थित एक प्राकृतिक मगरमच्छ आवास है।\n3. नारायणपुर जिले में जाटलूर नदी भी एक प्राकृतिक मगरमच्छ संरक्षण स्थल के रूप में कार्य करती है।\n\nऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All statements are correct. Chhattisgarh has 4 main crocodile conservation sites. Kotmi Sonar is artificial, while Bhaisadarha (Kanger river) and Jatloor river are major natural habitats.', 'सभी कथन सही हैं। छत्तीसगढ़ में 4 मुख्य मगरमच्छ संरक्षण स्थल हैं। कोटमी सोनार कृत्रिम है, जबकि भैंसादरहा (कांगेर नदी) और जाटलूर नदी प्रमुख प्राकृतिक आवास हैं।', 2),
(1304, 1199, 'When was the ''Chhattisgarh State CAMPA'' (Compensatory Afforestation Fund Management and Planning Authority) formally established, and what is its primary operational objective?', '''छत्तीसगढ़ राज्य कैम्पा'' (CAMPA - Compensatory Afforestation Fund Management and Planning Authority) औपचारिक रूप से कब स्थापित किया गया था, और इसका प्राथमिक परिचालन उद्देश्य क्या है?', 'May 2001; to grant land rights to forest dwellers', 'मई 2001; वनवासियों को भूमि अधिकार प्रदान करना', 'July 2009; compensatory afforestation for forest land diverted to non-forest uses', 'जुलाई 2009; गैर-वन उपयोगों के लिए परिवर्तित वन भूमि के लिए प्रतिपूरक वनीकरण', 'August 2014; to promote eco-tourism in national parks', 'अगस्त 2014; राष्ट्रीय उद्यानों में इको-टूरिज्म को बढ़ावा देना', 'February 2006; strictly to conserve medicinal plants', 'फरवरी 2006; कड़ाई से औषधीय पौधों का संरक्षण करना', 2, 'State CAMPA was established in July 2009. Its core objective is to undertake compensatory afforestation and environmental protection activities against the forest land diverted for non-forest (industrial/mining) uses.', 'राज्य कैम्पा की स्थापना जुलाई 2009 में हुई थी। इसका मुख्य उद्देश्य गैर-वन (औद्योगिक/खनन) उपयोगों के लिए परिवर्तित वन भूमि के एवज में प्रतिपूरक वनीकरण और पर्यावरण संरक्षण गतिविधियां करना है।', 3),
(1304, 1199, 'What is the designated area of the ''Lemru Elephant Reserve'', announced in August 2019 to mitigate human-elephant conflict, and which districts does it primarily cover?', 'मानव-हाथी संघर्ष को कम करने के लिए अगस्त 2019 में घोषित ''लेमरू हाथी रिजर्व'' का निर्धारित क्षेत्र क्या है, और यह मुख्य रूप से किन जिलों को कवर करता है?', '1143 sq. km; Jashpur, Balrampur, and Surajpur', '1143 वर्ग किमी; जशपुर, बलरामपुर, और सूरजपुर', '1995 sq. km; Korba, Raigarh, and Surguja', '1995 वर्ग किमी; कोरबा, रायगढ़, और सरगुजा', '2610 sq. km; Mungeli and Bilaspur', '2610 वर्ग किमी; मुंगेली और बिलासपुर', '552 sq. km; Gariaband and Dhamtari', '552 वर्ग किमी; गरियाबंद और धमतरी', 2, 'The Lemru Elephant Reserve officially covers an area of 1995 sq. km. It is a joint conservation effort spanning across the Korba, Raigarh, and Surguja districts to minimize human-elephant conflicts.', 'लेमरू हाथी रिजर्व आधिकारिक तौर पर 1995 वर्ग किमी क्षेत्र को कवर करता है। मानव-हाथी संघर्ष को कम करने के लिए यह कोरबा, रायगढ़ और सरगुजा जिलों में फैला एक संयुक्त संरक्षण प्रयास है।', 4),
(1304, 1199, 'Assertion (A): The Achanakmar-Amarkantak Biosphere Reserve is recognized as India''s 14th Biosphere Reserve.\n\nReason (R): It was officially included in UNESCO''s Man and the Biosphere (MAB) program in the year 2005.\n\nCodes:', 'कथन (A): अचानकमार-अमरकंटक बायोस्फीयर रिजर्व को भारत के 14वें बायोस्फीयर रिजर्व के रूप में मान्यता प्राप्त है।\n\nकारण (R): इसे आधिकारिक तौर पर वर्ष 2005 में यूनेस्को के मैन एंड द बायोस्फीयर (MAB) कार्यक्रम में शामिल किया गया था।\n\nकूट:', 'Both A and R are true, and R is the correct explanation of A', 'A और R दोनों सत्य हैं, और R, A का सही स्पष्टीकरण है', 'Both A and R are true, but R is NOT the correct explanation of A', 'A और R दोनों सत्य हैं, लेकिन R, A का सही स्पष्टीकरण नहीं है', 'A is true, but R is false', 'A सत्य है, लेकिन R असत्य है', 'A is false, but R is true', 'A असत्य है, लेकिन R सत्य है', 3, 'Assertion (A) is true as it was established as India''s 14th Biosphere Reserve in 2005. Reason (R) is false because it was included in UNESCO''s MAB program later, in the year 2012, not 2005.', 'कथन (A) सत्य है क्योंकि इसे 2005 में भारत के 14वें बायोस्फीयर रिजर्व के रूप में स्थापित किया गया था। कारण (R) गलत है क्योंकि इसे यूनेस्को के MAB कार्यक्रम में बाद में, वर्ष 2012 में शामिल किया गया था, न कि 2005 में।', 5),
(1304, 1199, 'Under the Joint Forest Management (JFM - Sanyukt Van Prabandhan) model in Chhattisgarh, what is the exact percentage of the state''s total forest area covered, and how many Forest Management Committees are operating?', 'छत्तीसगढ़ में संयुक्त वन प्रबंधन (JFM) मॉडल के तहत, राज्य के कुल वन क्षेत्र का सटीक प्रतिशत कितना कवर किया गया है, और कितनी वन प्रबंधन समितियां कार्यरत हैं?', '40.18% area and 5,432 committees', '40.18% क्षेत्र और 5,432 समितियां', '43.31% area and 6,105 committees', '43.31% क्षेत्र और 6,105 समितियां', '55.52% area and 7,887 committees', '55.52% क्षेत्र और 7,887 समितियां', '62.10% area and 8,012 committees', '62.10% क्षेत्र और 8,012 समितियां', 3, 'Joint Forest Management plays a huge role in community conservation. It covers 33,190 sq. km (exactly 55.52% of the total forest area) and is managed through 7,887 active Forest Management Committees.', 'सामुदायिक संरक्षण में संयुक्त वन प्रबंधन एक बड़ी भूमिका निभाता है। यह 33,190 वर्ग किमी (कुल वन क्षेत्र का ठीक 55.52%) को कवर करता है और इसे 7,887 सक्रिय वन प्रबंधन समितियों के माध्यम से प्रबंधित किया जाता है।', 6),
(1304, 1199, 'Consider the following statements regarding ''Tiger Reserves'' in Chhattisgarh:\n\n1. Indravati, Achanakmar, and Sitanadi-Udanti were all granted ''Tiger Reserve'' status simultaneously in 2009 by the state government.\n2. ''Project Tiger'' was first implemented in Indravati National Park in 1982-83.\n3. Guru Ghasidas National Park combined with Tamor Pingla Sanctuary constitutes the 4th Tiger Reserve of the state.\n\nWhich of the statement(s) given above is/are correct?', 'छत्तीसगढ़ में ''टाइगर रिजर्व'' के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. राज्य सरकार द्वारा 2009 में इंद्रावती, अचानकमार और सीतानदी-उदंती सभी को एक साथ ''टाइगर रिजर्व'' का दर्जा दिया गया था।\n2. ''प्रोजेक्ट टाइगर'' पहली बार 1982-83 में इंद्रावती राष्ट्रीय उद्यान में लागू किया गया था।\n3. गुरु घासीदास राष्ट्रीय उद्यान और तमोर पिंगला अभयारण्य मिलकर राज्य का चौथा टाइगर रिजर्व बनाते हैं।\n\nऊपर दिए गए कथनों में से कौन सा/से सही है/हैं?', '1 and 2 only', 'केवल 1 और 2', '2 and 3 only', 'केवल 2 और 3', '1 and 3 only', 'केवल 1 और 3', '1, 2, and 3', '1, 2, और 3', 4, 'All statements are correct. While Project Tiger started in Indravati in 1982-83 and in Achanakmar/Udanti in 2006, all three were officially notified as Tiger Reserves in 2009. The 4th is Guru Ghasidas-Tamor Pingla.', 'सभी कथन सही हैं। जबकि प्रोजेक्ट टाइगर 1982-83 में इंद्रावती में और 2006 में अचानकमार/उदंती में शुरू हुआ, 2009 में इन तीनों को आधिकारिक तौर पर टाइगर रिजर्व के रूप में अधिसूचित किया गया था। चौथा गुरु घासीदास-तमोर पिंगला है।', 7),
(1304, 1199, 'Chhattisgarh was officially declared an ''Herbal State'' on 4 July 2001 to conserve its rich medicinal flora. Under the UNDP project, how many ''Medicinal Plant Conservation Areas'' (MPCA) have been established in the state?', 'अपनी समृद्ध औषधीय वनस्पतियों के संरक्षण के लिए छत्तीसगढ़ को 4 जुलाई 2001 को आधिकारिक तौर पर ''हर्बल स्टेट'' घोषित किया गया था। UNDP परियोजना के तहत, राज्य में कितने ''औषधीय पौधा संरक्षित क्षेत्र'' (MPCA) स्थापित किए गए हैं?', '3', '3', '5', '5', '7', '7', '11', '11', 3, 'To protect its status as an Herbal State and conserve indigenous medicinal plants, exactly 7 Medicinal Plant Conservation Areas (MPCA) have been established under the UNDP project across various forest divisions.', 'हर्बल स्टेट के रूप में अपनी स्थिति की रक्षा करने और स्वदेशी औषधीय पौधों के संरक्षण के लिए, यूएनडीपी परियोजना के तहत विभिन्न वन मंडलों में ठीक 7 औषधीय पौधा संरक्षित क्षेत्र (MPCA) स्थापित किए गए हैं।', 8),
(1304, 1199, 'To conserve migratory and local birds, the Chhattisgarh government has developed specific Bird Sanctuaries (Pakshi Vihar). Where are the state''s FIRST and SECOND bird sanctuaries located respectively?', 'प्रवासी और स्थानीय पक्षियों के संरक्षण के लिए, छत्तीसगढ़ सरकार ने विशिष्ट पक्षी विहार विकसित किए हैं। राज्य का पहला और दूसरा पक्षी विहार क्रमशः कहाँ स्थित है?', 'Gidhwa-Parsada (Bemetara) and Rahangi (Bilaspur)', 'गिधवा-परसदा (बेमेतरा) और रहंगी (बिलासपुर)', 'Rahangi (Bilaspur) and Lamni (Jagdalpur)', 'रहंगी (बिलासपुर) और लमनी (जगदलपुर)', 'Gidhwa-Parsada (Bemetara) and Nandanvan (Raipur)', 'गिधवा-परसदा (बेमेतरा) और नंदनवन (रायपुर)', 'Kutumsar (Bastar) and Gidhwa-Parsada (Bemetara)', 'कुटुमसर (बस्तर) और गिधवा-परसदा (बेमेतरा)', 1, 'The state''s first dedicated bird sanctuary and bird festival site is Gidhwa-Parsada located in Bemetara district. The second bird sanctuary is established in Rahangi village, Bilaspur.', 'राज्य का पहला समर्पित पक्षी विहार और पक्षी महोत्सव स्थल बेमेतरा जिले में स्थित गिधवा-परसदा है। दूसरा पक्षी विहार रहंगी गांव, बिलासपुर में स्थापित है।', 9),
(1304, 1199, 'Assertion (A): The primary focus of Chhattisgarh''s State Forest Policy 2001 is on maximizing state revenue through the extensive commercial harvesting of timber.\n\nReason (R): The policy strictly emphasizes ecological balance, environmental stability, and the welfare of local tribal populations over mere economic profit.\n\nCodes:', 'कथन (A): छत्तीसगढ़ की राज्य वन नीति 2001 का प्राथमिक ध्यान लकड़ी की व्यापक व्यावसायिक कटाई के माध्यम से राज्य के राजस्व को अधिकतम करने पर है।\n\nकारण (R): यह नीति केवल आर्थिक लाभ के बजाय पारिस्थितिक संतुलन, पर्यावरणीय स्थिरता और स्थानीय आदिवासी आबादी के कल्याण पर कड़ाई से जोर देती है।\n\nकूट:', 'Both A and R are true, and R is the correct explanation of A', 'A और R दोनों सत्य हैं, और R, A का सही स्पष्टीकरण है', 'Both A and R are true, but R is NOT the correct explanation of A', 'A और R दोनों सत्य हैं, लेकिन R, A का सही स्पष्टीकरण नहीं है', 'A is true, but R is false', 'A सत्य है, लेकिन R असत्य है', 'A is false, but R is true', 'A असत्य है, लेकिन R सत्य है', 4, 'Assertion (A) is completely false because the Forest Policy 2001 explicitly prohibits viewing forests merely as a source of economic profit. Reason (R) is true, stating the actual objective of the policy.', 'कथन (A) पूरी तरह से गलत है क्योंकि वन नीति 2001 वनों को केवल आर्थिक लाभ के स्रोत के रूप में देखने से स्पष्ट रूप से रोकती है। कारण (R) सत्य है, जो नीति का वास्तविक उद्देश्य बताता है।', 10);
